// NORMALIZE TELEGRAM UPDATE (message OR callback_query)
// Outputs stable fields for downstream nodes.
//
// chat_id: number
// message_id: number (the message we should edit / reply to)
// cbq_id: string (callback query id)
// isCb: boolean
// cb_data: string
// from_id: number (user id)
// text: string (message text, if any)

const u = $json;

const msg = u.message ?? u.edited_message ?? u.channel_post ?? u.edited_channel_post ?? null;
const cb = u.callback_query ?? null;

const isCb = !!cb;

const chat_id = isCb ? cb.message?.chat?.id : msg?.chat?.id;
const message_id = isCb ? cb.message?.message_id : msg?.message_id;

const from_id = isCb ? cb.from?.id : msg?.from?.id;

const cbq_id = isCb ? cb.id : null;
const cb_data = isCb ? (cb.data ?? "") : "";

const text =
  (msg?.text ?? msg?.caption ?? "").toString();

return [{
  json: {
    isCb,
    chat_id,
    message_id,
    from_id,
    cbq_id,
    cb_data,
    text,
  }
}];

// PARSE ACTION + AUTH
// Reads Normalize output and decides which high-level action to run.
// - action: 'list' | 'help' | 'callback'
// - page: number (only for list, optional)
// - authorized: boolean

const norm = $json;

// ---- AUTH ----
// Put your allowed Telegram user IDs here:
const ALLOWED_USER_IDS = [
  // 123456789,
];

const authorized = ALLOWED_USER_IDS.length === 0
  ? true
  : ALLOWED_USER_IDS.includes(Number(norm.from_id));

// ---- ACTION ----
let action = "help";
let page = 0;

if (norm.isCb) {
  action = "callback";
} else {
  const t = String(norm.text || "").trim();

  // Commands: /start, /help, /pedidos, /list, etc.
  if (/^\/(pedidos|list)(\s|$)/i.test(t)) action = "list";
  else if (/^\/(start|help)(\s|$)/i.test(t)) action = "help";
  else if (t.toLowerCase() === "pedidos") action = "list";
}

// Optional: parse page from message like "/pedidos 2"
if (action === "list") {
  const m = String(norm.text || "").match(/\b(\d+)\b/);
  if (m) page = Math.max(0, Number(m[1]) - 1);
}

return [{
  json: {
    ...norm,
    authorized,
    action,
    page,
    limit: 5,
    offset: page * 5,
  }
}];

const in0 = $input.first().json;
const page = Number(in0.page || 0);
const limit = 5;
const offset = page * limit;
return [{ json: { ...in0, limit, offset } }];

// BUILD LIST (COMMON)
// Input: MySQL rows (multiple items). Context is taken from the nearest upstream control node.
// Output: { chat_id, message_id?, text, reply_markup }

const rows = $input.all().map(i => i.json);

// --- Context discovery (works both for /list and for callbacks) ---
const ctx =
  $items("Pagination")[0]?.json
  ?? $items("page")[0]?.json
  ?? $items("Parse Callback")[0]?.json
  ?? $json;

const page = Number(ctx.page ?? 0) || 0;
const chat_id = ctx.chat_id ?? null;
const message_id = ctx.message_id ?? null;

const orders = rows.filter(r => Number.isFinite(Number(r.id)));

let text = `📋 *Pedidos activos (página ${page + 1})*\n\nSeleccioná un pedido:`;

// Inline keyboard
const inline_keyboard = [];

for (const o of orders) {
  const id = Number(o.id);
  const cliente = (o.cliente_nombre ?? "").toString().trim();
  const estado = (o.estado ?? "Sin estado").toString().trim();
  const total = o.total != null ? Number(o.total) : null;

  const label = `#${id} — ${cliente || "Sin cliente"} — ${estado}${total != null ? " — $" + total.toFixed(2) : ""}`;

  // Telegram no permite forzar multiline en botones: hay un límite visual/UX del cliente.
  // Por eso: mostramos un resumen en el botón y el detalle completo se ve en el mensaje "view".
  inline_keyboard.push([
    { text: label.slice(0, 60), callback_data: `view|${id}` }
  ]);

  inline_keyboard.push([
    { text: "🔎 Ver detalle", callback_data: `view|${id}` },
    { text: "➡️ Avanzar", callback_data: `advance|${id}` },
  ]);
}

// Paging buttons
const prev = Math.max(0, page - 1);
const next = page + 1;

inline_keyboard.push([
  { text: "🔄 Actualizar", callback_data: `page|${page}` },
  { text: "⬅️ Ant", callback_data: `page|${prev}` },
  { text: "➡️ Sig", callback_data: `page|${next}` },
]);

return [{
  json: {
    chat_id,
    message_id,
    page,
    text,
    reply_markup: { inline_keyboard },
  }
}];

// PARSE CALLBACK DATA (expects Normalize + action='callback' path)
// callback_data examples:
// - "view|11"
// - "advance|11"
// - "page|0"

const norm = $json;

const data = String(norm.cb_data || "");
const parts = data.split("|");

const action = parts[0] || "";
let id = parts[1] ? Number(parts[1]) : null;
let page = parts[2] ? Number(parts[2]) : null;

// Special-case: page|N (2 parts)
if (action === "page" && page == null && id != null) {
  page = id;
  id = null;
}

return [{
  json: {
    action,
    id,
    page,
    cbq_id: norm.cbq_id,
    chat_id: norm.chat_id,
    message_id: norm.message_id,
  }
}];

const page = Number($json.page ?? 0);
const limit = 5;

return [
  {
    json: {
      ...$json,
      page,
      limit,
      offset: page * limit
    }
  }
