const row = $input.first().json;

// Definí acá tu flujo de estados (ajustalo a tus nombres reales)
const flow = [
  "Pago Verificado",
  "Producción",
  "Listo",
  "Entregado",
];

const current = String(row.estado ?? "").trim();

// Si el estado no está en la lista, arrancamos desde el primero
const idx = flow.indexOf(current);
const next = (idx === -1)
  ? flow[0]
  : flow[Math.min(idx + 1, flow.length - 1)];

return [{
  json: {
    id: Number(row.id),
    current,
    next,
  }
}];

