const row = $input.first()?.json ?? {};

// Contexto del callback (viene del Parse Callback)
const ctx = $node["Parse Callback"].json;

// Helpers
const fmtMoney = (n) => {
  const num = Number(n);
  if (!Number.isFinite(num)) return "-";
  return `$${num.toFixed(2)}`;
};

const safe = (v, fallback = "-") => {
  if (v === null || v === undefined) return fallback;
  const s = String(v).trim();
  return s.length ? s : fallback;
};

const id = Number(row.id ?? ctx.id);
const nombre = safe(row.nombre, "Pedido");
const estado = safe(row.estado, "Sin estado");
const cliente = safe(row.cliente_nombre, "Sin cliente");
const whatsapp = safe(row.whatsapp, "-");
const apertura = safe(row.apertura, "-");
const precio = fmtMoney(row.precio_final);

// Texto largo (acá sí se ve completo, no en botones)
const text =
`📄 *Detalle de pedido #${id}*
👤 *Cliente:* ${cliente}
📌 *Estado:* ${estado}
💰 *Total:* ${precio}
🕒 *Apertura:* ${apertura}
📱 *WhatsApp:* ${whatsapp}

_${nombre}_`;

// Botones: mantenelos cortos (Telegram recorta botones en móvil)
const inline_keyboard = [
  [
    { text: "➡️ Avanzar", callback_data: `advance|${id}` },
    { text: "🔄 Actualizar", callback_data: `view|${id}` },
  ],
  [
    // Volver a la lista: si no tenemos page, volvemos a 0
    { text: "⬅️ Volver a lista", callback_data: `page|${Number(ctx.page ?? 0) || 0}` },
  ],
];

// Si querés navegación desde detalle (opcional)
inline_keyboard.push([
  { text: "⬅️ Ant", callback_data: `page|${Math.max((Number(ctx.page ?? 0) || 0) - 1, 0)}` },
  { text: "➡️ Sig", callback_data: `page|${(Number(ctx.page ?? 0) || 0) + 1}` },
]);

return [{
  json: {
    text,
    replyMarkupObj: { inline_keyboard },
    // útil por si querés loguear
    id,
  }
}];
